package com.bank.batch;

import java.util.logging.*;

public class RateDemo {
    private static final Logger log = Logger.getLogger(RateDemo.class.getName());

    static {
        LogManager.getLogManager().reset();
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        log.addHandler(handler);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Pending transaction batches (item counts) and a 8-hour deadline
        int[] batches = {30, 110, 230, 100};
        int deadlineHours = 5;

        RateOptimizer optimizer = new RateOptimizer();
        int rate = optimizer.minRate(batches, deadlineHours);

        log.info("Finding minimum processing rate to clear batches before cutoff");
        log.info("Minimum rate -> " + rate + " items/hour per batch");
    }
}

