class RateOptimizer {
    private static final Logger log = Logger.getLogger(RateOptimizer.class.getName());

    // Binary search on the answer (rate). O(n log m) where m = max batch.
    int minRate(int[] batches, int deadlineHours) {
        int low = 1, high = 0;
        for (int b : batches) high = Math.max(high, b);  // fastest useful rate

        while (low < high) {
            int mid = low + (high - low) / 2;
            if (canFinish(batches, mid, deadlineHours)) {
                final int m = mid;
                log.fine(() -> "Rate " + m + " is feasible; trying slower");
                high = mid;                 // feasible: try to go slower
            } else {
                low = mid + 1;              // too slow: must go faster
            }
        }
        return low;                         // minimum feasible rate
    }

    // Feasibility check: hours needed at this rate <= deadline. Monotonic.
    private boolean canFinish(int[] batches, int rate, int deadlineHours) {
        long hours = 0;
        for (int b : batches) {
            hours += (b + rate - 1) / rate; // exact integer ceiling division
        }
        return hours <= deadlineHours;
    }
}

